   691→fun liquidation_inner<MarketType, DebtType, CollateralType>(
   692→    id: &mut UID,
   693→
   694→    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
   695→    emode_group: &mut EModeGroup,
   696→
   697→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
   698→
   699→    obligation: &mut Obligation<MarketType>,
   700→    liquidation_params: &LiquidationParams,
   701→
   702→    mut available_repay_coin: Coin<DebtType>,
   703→
   704→    coin_decimals_registry: &CoinDecimalsRegistry,
   705→    x_oracle: &XOracle,
   706→    clock: &Clock,
   707→
   708→    now: u64,
   709→
   710→    ctx: &mut TxContext,
   711→): (Coin<CollateralType>, Coin<DebtType>, u64) {
   712→    assert!(available_repay_coin.value() != 0, error::liquidation_zero_repay());
   713→
   714→    let debt_name = type_name::with_defining_ids<DebtType>();
   715→    let collateral_name = type_name::with_defining_ids<CollateralType>();
   716→
   717→    let obligation_old_borrow_amount = obligation.debt(debt_name).unsafe_debt_amount();
   718→
   719→    // update all assets interest in the obligation
   720→    refresh_obligation_assets_interest(assets, emode_group, reserves, obligation, now);
   721→
   722→    ensure_liquidate_borrow_allowed<MarketType, DebtType>(
   723→        liquidation_params,
   724→        obligation,
   725→        emode_group,
   726→        reserves,
   727→        coin_decimals_registry,
   728→        available_repay_coin.value(),
   729→        x_oracle,
   730→        clock,
   731→    );
   732→
   733→    // calculate how much collateral can be seized first
   734→    let obligation_latest_borrow_amount = obligation.debt(debt_name)
   735→        .unsafe_debt_amount()
   736→        // repay a bit more
   737→        .ceil();
   738→    let mut refund_coins = if (obligation_latest_borrow_amount < available_repay_coin.value()) {
   739→        let refund_amount = available_repay_coin.value() - obligation_latest_borrow_amount;
   740→        available_repay_coin.split(refund_amount, ctx)
   741→    } else {
   742→        sui::coin::zero(ctx)
   743→    };
   744→
   745→    // NOTE: disable rate limit
   746→
   747→    let collateral_reserve = reserves.load_mut_by_type(type_name::with_defining_ids<CollateralType>());
   748→    let exchange_rate = collateral_reserve.exchange_rate<MarketType>(); 
   749→
   750→    let mut seized_ctokens = liquidate_calculate_seize_ctokens<DebtType, CollateralType>(
   751→        exchange_rate,
   752→        liquidation_params.liquidation_incentive,
   753→        available_repay_coin.value(),
   754→        emode_group.get_oracle_base_token(),
   755→        x_oracle,
   756→        coin_decimals_registry,
   757→        clock,
   758→    );
   759→
   760→    // check if we need to refund debt coin because there might not be enough ctoken to be liquidated
   761→    let total_ctokens = obligation.ctoken_amount_by_coin(type_name::with_defining_ids<CollateralType>());
   762→    if (total_ctokens < seized_ctokens) {
   763→        let expected_repay_amount = float::from_quotient(total_ctokens, seized_ctokens)
   764→            .mul_u64(available_repay_coin.value())
   765→            // repay a bit more
   766→            .ceil();
   767→        let refund = available_repay_coin.value() - expected_repay_amount;
   768→
   769→        refund_coins.join(available_repay_coin.split(refund, ctx));
   770→        seized_ctokens = total_ctokens;
   771→    };
   772→
   773→    // at this stage, even if there is residual, it should be a very small amount, let the protocol consume the residual
   774→    let _residual = obligation.unsafe_repay_debt_only<MarketType, DebtType>(available_repay_coin.value());
   775→
   776→    let ctoken_balance = obligation.withdraw_ctokens<MarketType, CollateralType>(seized_ctokens);
   777→    let ctoken_balance_amount = ctoken_balance.value();
   778→    let refund_balance = collateral_reserve.liquidate_ctokens<MarketType, CollateralType>(
   779→        ctoken_balance.into_coin(ctx),
   780→        liquidation_params.liquidation_revenue_factor,
   781→    );
   782→
   783→    let obligation_new_borrow_amount = if (!obligation.has_debt(debt_name)) { float::zero() } else { obligation.debt(debt_name).unsafe_debt_amount() };
   784→    emode_group.update_asset_borrow(debt_name, obligation_old_borrow_amount, obligation_new_borrow_amount);
   785→
   786→    let debt_reserve = reserves.load_mut_by_type(debt_name);
   787→    debt_reserve.repay_amount<MarketType, DebtType>(available_repay_coin);
   788→
   789→    try_stop_borrow_deleverage<MarketType, DebtType>(id, obligation.emode_group(), emode_group, debt_name);
   790→    try_stop_collateral_deleverage<MarketType, CollateralType>(id, reserves, collateral_name);

